/**
 * Next.js bazen .next/server/edge-instrumentation.js dosyasını bekliyor ama üretmiyor (ENOENT).
 * Bu script build sonrası veya dev öncesi eksikse no-op dosyayı oluşturur.
 */
const fs = require('fs');
const path = require('path');

const outPath = path.join(process.cwd(), '.next', 'server', 'edge-instrumentation.js');
const content = `"use strict";
// No-op edge instrumentation (generated by scripts/ensure-edge-instrumentation.js)
exports.register = async function register() {};
`;

const dir = path.dirname(outPath);
if (!fs.existsSync(dir)) {
  fs.mkdirSync(dir, { recursive: true });
}
if (fs.existsSync(outPath)) process.exit(0);

fs.writeFileSync(outPath, content, 'utf8');
console.log('Created .next/server/edge-instrumentation.js (stub)');
